  privacy: {
    title: "Política de privacidad",
    updated: "Última actualización: mayo de 2025",
    intro:
      "vitecamion concede gran importancia a la protección de tus datos personales. Esta política describe qué datos recopilamos, por qué los recopilamos, cuánto tiempo los conservamos y qué derechos tienes en virtud del Reglamento General de Protección de Datos (RGPD – UE 2016/679).",
    sections: [
      {
        title: "1. Responsable del tratamiento",
        body: "El responsable del tratamiento es VITECAMION, una sociedad por acciones simplificada (SAS) constituida conforme al derecho francés, con domicilio social en 17 Rue du Moulin, 77820 Le Châtelet-en-Brie, Francia. Contacto: info@vitecamion.com.",
      },
      {
        title: "2. Datos recopilados y finalidades",
        body: "Recopilamos los siguientes datos personales: (a) Datos de reserva – nombre, dirección de correo electrónico, número de teléfono – recopilados al enviar una solicitud de reserva, necesarios para la ejecución del contrato de alquiler. (b) Datos de pago – procesados exclusivamente por nuestro socio de pago Stripe; vitecamion no almacena los datos de tu tarjeta. (c) Datos GPS / de ubicación – registrados durante las sesiones de alquiler activas para garantizar la seguridad del vehículo y verificar el periodo de alquiler, sobre la base del interés legítimo. (d) Datos de facturación – nombre, correo electrónico y detalles de la transacción conservados por motivos contables y de cumplimiento legal. (e) Datos técnicos – cookie de sesión necesaria para la autenticación en el sitio. (f) Datos de pedidos de la tienda – nombre, correo electrónico, número de teléfono y dirección de envío, recopilados al realizar un pedido en nuestra tienda online, necesarios para la ejecución del contrato de venta y la entrega de tu pedido. (g) Datos de la lista de deseos – los productos que guardas en tu lista de deseos se almacenan únicamente en el almacenamiento local de tu navegador y nunca se transmiten ni se procesan en nuestros servidores.",
      },
      {
        title: "3. Base jurídica del tratamiento",
        body: "Según la actividad de tratamiento: necesidad contractual (ejecución de la reserva, ejecución del pedido de la tienda); obligación legal (conservación de facturas durante 10 años según la normativa contable francesa); interés legítimo (seguimiento del vehículo, prevención del fraude); consentimiento (cualquier comunicación opcional a la que te hayas suscrito).",
      },
      {
        title: "4. Plazos de conservación",
        body: "Datos de reservas, pedidos de la tienda y facturación: 5 años tras la última interacción, o 10 años cuando lo exija la normativa contable. Datos de seguimiento GPS: eliminados en un plazo de 24 horas tras finalizar el periodo de alquiler. Cookies de sesión: caducan a los 5 días como máximo. Datos relativos a reservas canceladas o no confirmadas: eliminados a los 90 días. Carritos de la tienda abandonados: eliminados tras 30 días de inactividad.",
      },
      {
        title: "5. Carrito de la tienda y lista de deseos (almacenamiento local)",
        body: "Nuestra tienda online utiliza el almacenamiento local de tu navegador para dos fines. Un token de carrito anónimo (shop_cart_token) se almacena en tu dispositivo y se utiliza para recuperar el contenido de tu carrito, que se conserva en nuestros servidores hasta el pago o su caducidad. Tu lista de deseos (shop_wishlist) se almacena por completo en tu navegador y nunca se envía a nuestros servidores ni se procesa en ellos; al borrar los datos de tu navegador se eliminará de forma permanente.",
      },
      {
        title: "6. Destinatarios de tus datos",
        body: "Tus datos pueden compartirse con los siguientes subencargados del tratamiento, cada uno vinculado por acuerdos de tratamiento de datos conformes al RGPD: Stripe Inc. (procesamiento de pagos, EE. UU. – cubierto por Cláusulas Contractuales Tipo); Google Cloud (almacenamiento de facturas en PDF, región de la UE); proveedor de envío de correos electrónicos (correos transaccionales). Los pedidos de la tienda son preparados y enviados directamente por vitecamion. Nunca vendemos tus datos personales.",
      },
      {
        title: "7. Transferencias internacionales",
        body: "Stripe Inc. está establecida en Estados Unidos. Las transferencias están cubiertas por Cláusulas Contractuales Tipo aprobadas por la Comisión Europea. El almacenamiento en Google Cloud está configurado para permanecer dentro de la UE. No se realizan otras transferencias internacionales.",
      },
      {
        title: "8. Tus derechos",
        body: "En virtud del RGPD tienes derecho a: acceder a tus datos, solicitar su rectificación o supresión, oponerte al tratamiento, solicitar la limitación del tratamiento y recibir tus datos en un formato portable. Para ejercer cualquier derecho, envía un correo a info@vitecamion.com. También tienes derecho a presentar una reclamación ante la CNIL (www.cnil.fr).",
      },
      {
        title: "9. Seguridad de los datos",
        body: "Aplicamos medidas técnicas y organizativas adecuadas para proteger tus datos: cifrado HTTPS/TLS en tránsito, controles de acceso en todos los sistemas, cookies de sesión HTTPONLY. Ningún método de transmisión por Internet es 100% seguro; te notificaremos con prontitud en caso de una vulneración que afecte a tus derechos.",
      },
      {
        title: "10. Cookies",
        body: "Utilizamos una única cookie de sesión esencial (vitecamion_auth) estrictamente necesaria para la autenticación. No utilizamos cookies publicitarias ni de perfilado. Nuestro socio de pago Stripe puede establecer sus propias cookies durante el proceso de pago; consulta la política de privacidad de Stripe para más información.",
      },
      {
        title: "11. Cambios en esta política",
        body: "Podemos actualizar esta política cuando cambien nuestras prácticas. Indicaremos la fecha de revisión en la parte superior de la página. Para cambios significativos te notificaremos por correo electrónico si disponemos de tu dirección.",
      },
      {
        title: "12. Contacto",
        body: "Para cualquier pregunta relacionada con la privacidad o para ejercer tus derechos, contáctanos en: info@vitecamion.com — o por correo postal a: vitecamion, 17 Rue du Moulin, 77820 Le Châtelet-en-Brie, Francia.",
      },
    ],
  },
