        title: "4. Aufbewahrungsfristen",
        body: "Buchungs-, Shop-Bestell- und Rechnungsdaten: 5 Jahre nach der letzten Interaktion, oder 10 Jahre, wenn nach Buchhaltungsvorschriften erforderlich. GPS-Trackingdaten: gelöscht innerhalb von 24 Stunden nach Ende des Mietzeitraums. Sitzungscookies: laufen nach maximal 5 Tagen ab. Daten zu stornierten oder unbestätigten Buchungen: nach 90 Tagen gelöscht. Verlassene Shop-Warenkörbe: nach 30 Tagen Inaktivität gelöscht.",
